; PhoenixMISER PT68C268 power-management module (E800 segment)
; segment E800, 24576 (0x6000) bytes; generated by tools/romdis.py - labels are best guesses
;

rom_header:
        ; 55AA option ROM signature, size 30h*512 = 24 KB. Lives at E800:0000 at runtime (system BIOS far-calls E800:0010 etc).
        ; [data] option ROM header
E800:0000                              db  55 AA 30                                        ; U.0

init_stub:
        ; Option ROM init entry: RETF - nothing to do at scan time
E800:0003 CB                           retf

miser_signature:
        ; 'PhoenixMISER' identification string
        ; [data] signature
        ; [data] string
E800:0004                              db  'PhoenixMISER'

api_entry_10:  ; xrefs: 5514
        ; Far-callable entry table (each is call near ; retf). Called from system BIOS at F000:98F9 and jumped to from F000:5940 (POST start).
E800:0010 E8 11 16                     call    miser_post_hook
E800:0013 CB                           retf
E800:0014                              db  00 00 00 00 00 00 00 00                         ; ........

